#!/usr/bin/env python3
"""Apply script: policy start date + per-subgroup LR + category LR in Portfolio Insights.

Run from the HealthCross repo root: python3 apply_portfolio_insights_subgroup_category.py
"""
import base64, hashlib, os, sys

MARKER = "PORTFOLIO_INSIGHTS_SUBGROUP_CATEGORY_2026_08_04"

FILES = [
    {
        'path': 'app/api/routes_portfolio_analysis.py',
        'sha256': '9a51b21488a75c48ea6511f8e106ae142f233bf3913670657e64ec5b8512a3a8',
        'size': 23625,
        'b64': '',
    },
    {
        'path': 'app/scoring/rules/portfolio_analysis.py',
        'sha256': '52a28e297b84bae3e08819ab1819ff1aa36a52ee465da59284be51354f67b766',
        'size': 24064,
        'b64': '',
    },
    {
        'path': 'app/static/index.html',
        'sha256': 'c4154d761c5e7afcb84f909001935bb887bbda990e7cc196df29a6bf4a20a535',
        'size': 159404,
        'b64': '',
    },
    {
        'path': 'tests/test_api_portfolio_analysis.py',
        'sha256': '84d92dc89b35659cfe3ad05ca595857a293a0e52672b7ce4c61d4460946d74a4',
        'size': 35077,
        'b64': '',
    },
    {
        'path': 'tests/test_portfolio_analysis.py',
        'sha256': '9680fd8ed8c8595798708e53db5857fcc34c0651be37bfd2eb4277ed616cbeb8',
        'size': 33141,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (should show 478 passed)")
        print("Then: git add -A && git commit -m '...' && git push")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
